<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import DataGrid, { type GridColumn } from "@/components/DataGrid.vue";
import StatusBadge from "@/components/StatusBadge.vue";
import { ApiError } from "@/services/http";
import { useAuthSession } from "@/composables/useAuthSession";
import { blockCard, getAdministrativeState, getTarjeta, listAdministrativeHistory, listCardHistory, retireCard, unblockCard, type EstadoAdministrativo, type HistorialEstadoAdministrativo, type HistorialPaginated, type Tarjeta } from "@/services/tarjetas";

const route = useRoute(); const router = useRouter(); const session = useAuthSession();
const id = String(route.params.id); const card = ref<Tarjeta | null>(null); const tab = ref<"history" | "administrative">("history"); const administrative = ref<EstadoAdministrativo|null>(null); const administrativeHistory = ref<HistorialEstadoAdministrativo[]>([]); const administrativePage = ref(1); const administrativePagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 }); const administrativeLoading = ref(false); const administrativeError = ref(""); const administrativeReason = ref(""); const reasonAttempted = ref(false);
const loading = ref(true); const saving = ref(false); const error = ref(""); const success = ref("");
const history = ref<HistorialPaginated[]>([]); const historyPage = ref(1); const historyPages = ref(0); const historyTotal = ref(0); const historyLoading = ref(false); const historyError = ref("");
const historyColumns: GridColumn[] = [{ key: "fecha", label: "Fecha", width: "15%" }, { key: "tipo", label: "Tipo", width: "10%" }, { key: "nombreBeneficiario", label: "Beneficiario", width: "17%" }, { key: "codigoSolicitud", label: "Solicitud", width: "12%" }, { key: "perfilesAcceso", label: "Perfil", width: "14%" }, { key: "vigencia", label: "Vigencia", width: "17%" }, { key: "nombreEstadoAsignacion", label: "Estado", width: "10%" }, { key: "usuarioResponsable", label: "Responsable", width: "15%" }];
const administrativeHistoryColumns: GridColumn[] = [{ key: "fecha", label: "Fecha", width: "17%" }, { key: "anterior", label: "Estado anterior", width: "17%" }, { key: "nuevo", label: "Estado nuevo", width: "17%" }, { key: "motivo", label: "Motivo", width: "31%" }, { key: "responsable", label: "Responsable", width: "18%" }];
const message = (e: unknown) => e instanceof ApiError ? e.message : "Ocurrió un error inesperado";
const canAdministrativeDeactivate = computed(() => session.user.value?.permissions.includes("TARJETAS_DESACTIVAR") ?? false);
const canAdministrativeActivate = computed(() => session.user.value?.permissions.includes("TARJETAS_ACTIVAR") ?? false);
const reasonError = computed(() => administrativeReason.value.trim() ? "" : "Indique el motivo del cambio para continuar.");
async function loadCard() { try { card.value = await getTarjeta(id); } catch (e) { error.value = message(e); } finally { loading.value = false; } }
async function loadHistory(page = 1) { historyLoading.value = true; historyError.value = ""; history.value = []; try { const response = await listCardHistory(id, page); history.value = response.items; historyPage.value = page; historyPages.value = response.pagination.totalPages; historyTotal.value = response.pagination.total; } catch (e) { historyError.value = message(e); } finally { historyLoading.value = false; } }
async function loadAdministrative(page = 1) { administrativeLoading.value = true; administrativeError.value = ""; try { const [state, historyResponse] = await Promise.all([getAdministrativeState(id), listAdministrativeHistory(id, page)]); administrative.value = state; administrativeHistory.value = historyResponse.items; administrativePagination.value = historyResponse.pagination; administrativePage.value = page; } catch (e) { administrativeError.value = message(e); } finally { administrativeLoading.value = false; } }
function administrativeHistoryRow(item: HistorialEstadoAdministrativo): Record<string, unknown> { return { ...item, fecha: new Date(item.fechaRegistro).toLocaleString("es-HN"), anterior: item.nombreEstadoTarjetaAnterior ?? "Inicio", nuevo: item.nombreEstadoTarjetaNuevo, motivo: item.motivoCambio, responsable: item.usuarioRegistro }; }
async function administrativeAction(action: "block"|"unblock"|"retire") { reasonAttempted.value = true; if (!administrativeReason.value.trim()) { error.value = "El motivo es obligatorio."; return; } saving.value=true; try { if(action === "block") await blockCard(id, administrativeReason.value); else if(action === "unblock") await unblockCard(id, administrativeReason.value); else await retireCard(id, administrativeReason.value); administrativeReason.value=""; reasonAttempted.value = false; success.value="Estado administrativo actualizado."; await Promise.all([loadCard(),loadAdministrative()]); } catch(e) { error.value=message(e); } finally { saving.value=false; } }
function historyRow(item: HistorialPaginated): Record<string, unknown> { return { ...item, fecha: new Date(item.fechaAsignacion).toLocaleString("es-HN"), tipo: "Asignación", vigencia: `${item.fechaInicioVigencia?.slice(0, 10)} — ${item.fechaFinVigencia?.slice(0, 10) ?? "Sin vencimiento"}` }; }
onMounted(() => { void session.restore(); void Promise.all([loadCard(), loadHistory()]); });
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Operación', to: '/' }, { label: 'Tarjetas', to: '/tarjetas' }, { label: 'Gestión' }]" />
  <div class="bo-page-head"><div><p class="bo-eyebrow">Operación / Tarjetas / Gestión</p><h1>Gestionar tarjeta <span v-if="card">· {{ card.codigoTarjeta }}</span></h1><p>Administración institucional de asignación, vigencia e historial.</p></div><button class="bo-btn" @click="router.push('/tarjetas')">← Regresar al listado</button></div>
  <div v-if="error" class="bo-state-error bo-notice">{{ error }} <button class="bo-link" @click="loadCard">Reintentar</button></div><div v-if="success" class="bo-notice">{{ success }}</div>
  <div v-if="loading" class="bo-state">Cargando tarjeta...</div>
  <template v-else-if="card">
    <section class="bo-card tarjeta-summary"><div><small>Código</small><strong>{{ card.codigoTarjeta }}</strong></div><div><small>Serie</small><strong>{{ card.numeroSerie ?? "—" }}</strong></div><div><small>Estado</small><strong>{{ card.nombreEstadoTarjeta }}</strong></div><div><small>Asignación</small><strong>{{ card.idAsignacion ? card.nombreEstadoAsignacion : "Disponible" }}</strong></div><div><small>Beneficiario actual</small><strong>{{ card.nombreBeneficiario ?? "—" }}</strong></div><div><small>Perfil actual</small><strong>{{ card.perfilesAcceso ?? "—" }}</strong></div><div><small>Vigencia</small><strong>{{ card.idAsignacion ? `${card.fechaInicioVigencia?.slice(0,10)} — ${card.fechaFinVigencia?.slice(0,10) ?? "Sin vencimiento"}` : "—" }}</strong></div><div><small>Fecha de registro</small><strong>{{ new Date(card.fechaRegistro).toLocaleString('es-HN') }}</strong></div></section>
     <nav class="tarjeta-tabs" aria-label="Secciones de gestión"><button :class="{ active: tab === 'history' }" @click="tab = 'history'; loadHistory()">Historial</button><button :class="{ active: tab === 'administrative' }" @click="tab = 'administrative'; loadAdministrative()">Estado administrativo</button></nav>
     <section v-if="tab === 'history'" class="tarjeta-panel"><DataGrid :columns="historyColumns" :rows="history.map(historyRow)" :row-key="item => String(item.idAsignacion)" :pagination="{ page: historyPage, pageSize: 10, total: historyTotal, totalPages: historyPages }" :loading="historyLoading" :error="historyError" empty-text="No hay eventos históricos almacenados para esta tarjeta." @page="loadHistory"><template #cell-nombreBeneficiario="{ row }">{{ row.nombreBeneficiario }}</template><template #cell-perfilesAcceso="{ row }">{{ row.perfilesAcceso ?? "—" }}</template><template #cell-usuarioResponsable="{ row }">{{ row.usuarioResponsable ?? "—" }}</template></DataGrid></section>
<section v-else class="bo-card tarjeta-panel administrative-panel"><div class="administrative-section-head"><div><h2>Gestión del estado administrativo</h2><p>Registre el motivo y seleccione una acción válida para el estado actual de la tarjeta.</p></div><StatusBadge v-if="administrative" :active="administrative.codigoEstadoTarjeta !== 'BAJA' && administrative.codigoEstadoTarjeta !== 'BLOQUEADA'" /></div><div v-if="administrative?.codigoEstadoTarjeta === 'BLOQUEADA' && administrative.idAsignacion" class="bo-notice bo-state-warning" role="status">La tarjeta está bloqueada, pero conserva su asignación vigente.</div><form class="bo-form administrative-form" @submit.prevent><label class="administrative-reason">Motivo del cambio <span>(obligatorio)</span><textarea v-model="administrativeReason" maxlength="1000" rows="5" placeholder="Describa el motivo de la operación administrativa" :aria-invalid="Boolean(reasonAttempted && reasonError)" aria-describedby="administrative-reason-help" /></label><p id="administrative-reason-help" class="administrative-help">El motivo quedará registrado en el historial administrativo.</p><p v-if="reasonAttempted && reasonError" class="bo-form-error" role="alert">{{ reasonError }}</p><div class="bo-form-actions administrative-actions"><button v-if="(administrative?.codigoEstadoTarjeta === 'DISPONIBLE' || administrative?.codigoEstadoTarjeta === 'ASIGNADA') && canAdministrativeDeactivate" type="button" class="bo-btn bo-btn-primary" :disabled="saving" @click="administrativeAction('block')">{{ saving ? 'Procesando…' : 'Bloquear tarjeta' }}</button><button v-if="administrative?.codigoEstadoTarjeta === 'BLOQUEADA' && canAdministrativeActivate" type="button" class="bo-btn bo-btn-primary" :disabled="saving" @click="administrativeAction('unblock')">{{ saving ? 'Procesando…' : 'Desbloquear tarjeta' }}</button><button v-if="administrative?.codigoEstadoTarjeta !== 'BAJA' && !administrative?.idAsignacion && canAdministrativeDeactivate" type="button" class="bo-btn administrative-danger" :disabled="saving" @click="administrativeAction('retire')">{{ saving ? 'Procesando…' : 'Dar de baja' }}</button></div></form><div class="administrative-history"><div class="administrative-section-head"><div><h2>Historial administrativo</h2><p>Registro de cambios de estado y responsables.</p></div></div><DataGrid :columns="administrativeHistoryColumns" :rows="administrativeHistory.map(administrativeHistoryRow)" :row-key="item => String(item.idTarjetaEstado)" :pagination="administrativePagination" :loading="administrativeLoading" :error="administrativeError" empty-text="No hay cambios administrativos registrados para esta tarjeta." @page="loadAdministrative"><template #cell-anterior="{ row }"><span class="administrative-state">{{ row.anterior }}</span></template><template #cell-nuevo="{ row }"><span class="administrative-state administrative-state-new">{{ row.nuevo }}</span></template><template #cell-motivo="{ row }"><span class="administrative-reason-cell">{{ row.motivo }}</span></template></DataGrid></div></section>
  </template>
</template>

<style>
.administrative-panel { display: grid; gap: 24px; }
.administrative-section-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.administrative-section-head h2 { margin: 0 0 5px; }
.administrative-section-head p { margin: 0; color: var(--bo-muted); font-size: 12px; line-height: 1.5; }
.administrative-form { gap: 6px; padding: 18px; border: 1px solid var(--bo-line); border-radius: 8px; background: #f8fafb; }
.administrative-reason { display: grid; gap: 7px; color: var(--bo-dark); font-size: 12px; font-weight: 700; }
.administrative-reason span { color: var(--bo-muted); font-weight: 400; }
.administrative-reason textarea { width: 100%; box-sizing: border-box; min-height: 128px; resize: vertical; padding: 11px 12px; border: 1px solid var(--bo-line); border-radius: 6px; color: var(--bo-text); background: #fff; font: inherit; font-size: 13px; line-height: 1.5; }
.administrative-reason textarea:focus { outline: 2px solid rgb(0 90 135 / 16%); border-color: var(--bo-blue); }
.administrative-reason textarea[aria-invalid="true"] { border-color: #b75b5b; }
.administrative-help { margin: 0; color: var(--bo-muted); font-size: 11px; }
.administrative-actions { justify-content: flex-start; margin-top: 10px; }
.administrative-danger { color: #a03b3b; border-color: #e4bebe; background: #fff; }
.bo-state-warning { border-color: #e8d49c; color: #785c13; background: #fff8df; }
.administrative-history { display: grid; gap: 14px; min-width: 0; }
.administrative-history .siga-grid-table { min-width: 700px; }
.administrative-history .siga-grid-table td { white-space: normal; overflow-wrap: anywhere; }
.administrative-state { color: var(--bo-text); font-weight: 700; }
.administrative-state::before { content: ""; display: inline-block; width: 6px; height: 6px; margin: 0 7px 2px 0; border-radius: 50%; background: var(--bo-muted); }
.administrative-state-new::before { background: var(--bo-blue); }
.administrative-reason-cell { display: block; min-width: 150px; line-height: 1.45; }
@media (max-width: 600px) { .administrative-section-head { flex-direction: column; }.administrative-panel { gap: 18px; }.administrative-form { padding: 14px; }.administrative-actions { align-items: stretch; flex-direction: column; }.administrative-actions .bo-btn { width: 100%; } }
</style>
